SELECT a.id AS applyId, a.cnsl_aply_id AS cnslAplyId, e.empl_nm AS counselorName, a.type_cd AS counselingType, a.method_cd AS counselingMethod, a.stat_cd AS status, a.aply_dttm AS applyDateTime, a.content, r.id AS resultId, r.cnsl_cn AS resultContent, r.satisf_score AS satisfactionScore, r.cnsl_dttm AS counselingDateTime FROM cnsl_aply a LEFT JOIN empl_info e ON a.empl_no = e.empl_no LEFT JOIN cnsl_rslt r ON a.cnsl_aply_id = r.cnsl_aply_id WHERE a.std_no = #{stdNo}
AND a.aply_dttm >= #{startDate}
AND a.stat_cd IN ('PENDING', 'APPROVED')
AND a.stat_cd = #{status}
AND a.type_cd = #{type}
ORDER BY a.aply_dttm ASC

        SELECT
            COUNT(*)
        FROM
            cnsl_aply a
        JOIN
            empl_info e ON a.empl_no = e.empl_no
        LEFT JOIN
            cnsl_rslt r ON a.cnsl_aply_id = r.cnsl_aply_id

	    a.std_no = #{stdNo}

	        AND a.aply_dttm >= #{startDate}




	                AND a.stat_cd IN ('PENDING', 'APPROVED')


	                AND a.stat_cd = #{status}




	        AND a.type_cd = #{type}
